using FreeSql; using VelrixWorkHub.Application.SalesOrders; using VelrixWorkHub.Domain;
namespace VelrixWorkHub.Infrastructure.SalesOrders;
public sealed class FreeSqlSalesOrderRepository(IFreeSql fsql) : ISalesOrderRepository { public IReadOnlyList<SalesOrder> List() => fsql.Select<SalesOrderRecord>().ToList().Select(x => SalesOrder.Restore(x.Id,x.OrderNo,x.CustomerId,x.ProductId,DateOnly.FromDateTime(x.OrderDate),x.Quantity,x.UnitPrice,x.Status,x.ContractId,x.PmsProjectId,x.DueDate is null ? null : DateOnly.FromDateTime(x.DueDate.Value))).ToArray(); public void Add(SalesOrder x) => fsql.Insert(ToRecord(x)).ExecuteAffrows(); public void Update(SalesOrder x) { if (fsql.Update<SalesOrderRecord>().Set(y=>y.Status,x.Status).Where(y=>y.Id==x.Id).ExecuteAffrows()==0) throw new InvalidOperationException("销售订单不存在或已被删除。"); } private static SalesOrderRecord ToRecord(SalesOrder x)=>new(){Id=x.Id,OrderNo=x.OrderNo,CustomerId=x.CustomerId,ProductId=x.ProductId,ContractId=x.ContractId,PmsProjectId=x.PmsProjectId,OrderDate=x.OrderDate.ToDateTime(TimeOnly.MinValue),Quantity=x.Quantity,UnitPrice=x.UnitPrice,Status=x.Status,DueDate=x.DueDate.ToDateTime(TimeOnly.MinValue)}; }
